/**
 * RAFLoop — clean requestAnimationFrame wrapper with start/stop, auto-pause on hidden.
 * Based on Vidstack RAFLoop.
 */
export class RAFLoop {
  /**
   * @param {function(number): void} callback — called each frame with timestamp
   */
  constructor(callback) {
    this._callback = callback;
    this._rafId = 0;
    this._running = false;
    this._onVisibilityChange = () => {
      if (document.hidden) {
        this._cancelFrame();
      } else if (this._running) {
        this._requestFrame();
      }
    };
  }

  /**
   * Begin the RAF loop.
   */
  start() {
    if (this._running) return;
    this._running = true;
    document.addEventListener('visibilitychange', this._onVisibilityChange);
    this._requestFrame();
  }

  /**
   * Cancel the RAF loop.
   */
  stop() {
    this._running = false;
    this._cancelFrame();
    document.removeEventListener('visibilitychange', this._onVisibilityChange);
  }

  /**
   * Whether the loop is currently running.
   * @returns {boolean}
   */
  get running() {
    return this._running;
  }

  /** @internal */
  _requestFrame() {
    this._cancelFrame();
    this._rafId = requestAnimationFrame((ts) => {
      if (!this._running) return;
      this._callback(ts);
      this._requestFrame();
    });
  }

  /** @internal */
  _cancelFrame() {
    if (this._rafId) {
      cancelAnimationFrame(this._rafId);
      this._rafId = 0;
    }
  }
}
